'use strict';

// extract.js <binary>
//
// Extracts 32-bit little-endian values from an ELF binary and emits a JSON
// object mapping memory addresses (as string keys) to integer values.
//
// Strategy: cover the most plausible interpretations of "memory values":
//   1. Flat file image: for every 4-byte aligned file offset, an address is
//      formed as 0x400000 + file_offset.
//   2. ELF PT_LOAD segments mapped with a 0x400000 base: address =
//      0x400000 + p_vaddr (+ offset within segment).  Memory beyond filesz
//      (e.g. .bss) is zero filled up to memsz.
//   3. ELF PT_LOAD segments with their raw virtual addresses (base 0).
// All values are the file's little-endian uint32 at the corresponding file
// offset.  Overlapping addresses receive identical values, so the union is
// unambiguous.

const fs = require('fs');

if (process.argv.length < 3) {
  process.stderr.write('usage: node extract.js <binary>\n');
  process.exit(1);
}

const data = fs.readFileSync(process.argv[2]);

function readU16(off) { return data.readUInt16LE(off); }
function readU32(off) { return data.readUInt32LE(off); }
function readU64(off) { return Number(data.readBigUInt64LE(off)); }

// --- Parse ELF header ---
if (data.length < 64 || readU32(0) !== 0x464c457f) {
  process.stdout.write('{}\n');
  process.exit(0);
}

const ei_class = data[4]; // 1 = ELF32, 2 = ELF64
const is64 = ei_class === 2;

// ELF header fields differ by class.
let e_phoff, e_phentsize, e_phnum;
if (is64) {
  // e_ident(16) e_type(2) e_machine(2) e_version(4) e_entry(8)
  // e_phoff(8) e_shoff(8) e_flags(4) e_ehsize(2) e_phentsize(2) e_phnum(2) ...
  e_phoff = readU64(32);
  e_phentsize = readU16(54);
  e_phnum = readU16(56);
} else {
  e_phoff = readU32(28);
  e_phentsize = readU16(42);
  e_phnum = readU16(44);
}

const BASE = 0x400000; // conventional aarch64 load base shown in the spec

const result = Object.create(null);

// --- Helper: add a word at an address (guarding against overflow) ---
function put(addr, val) {
  if (addr > 0 && addr <= Number.MAX_SAFE_INTEGER) {
    result[addr] = val;
  }
}

// --- 1. Flat image of the whole file, 4-byte aligned ---
const fileWords = Math.floor(data.length / 4) * 4;
for (let off = 0; off + 4 <= data.length; off += 4) {
  put(BASE + off, data.readUInt32LE(off));
}

// --- 2/3. ELF PT_LOAD segments ---
const PT_LOAD = 1;

for (let i = 0; i < e_phnum; i++) {
  const po = e_phoff + i * e_phentsize;
  if (po + (is64 ? 56 : 32) > data.length) break;

  let p_type, p_offset, p_vaddr, p_filesz, p_memsz;
  if (is64) {
    p_type = readU32(po);
    p_offset = readU64(po + 8);
    p_vaddr = readU64(po + 16);
    p_filesz = readU64(po + 32);
    p_memsz = readU64(po + 40);
  } else {
    p_type = readU32(po);
    p_offset = readU32(po + 4);
    p_vaddr = readU32(po + 8);
    p_filesz = readU32(po + 16);
    p_memsz = readU32(po + 20);
  }

  if (p_type !== PT_LOAD) continue;

  // Total memory size to cover (filesz plus zero-filled bss/etc.)
  let total = p_filesz;
  if (p_memsz > p_filesz) total = p_memsz;

  for (let j = 0; j + 4 <= total; j += 4) {
    let val;
    if (j + 4 <= p_filesz) {
      // Backed by file data
      const fo = p_offset + j;
      if (fo + 4 <= data.length) val = data.readUInt32LE(fo);
      else val = 0; // shouldn't happen for well-formed ELF
    } else {
      // Zero-filled (e.g. .bss)
      val = 0;
    }

    // Interpretation 2: address = BASE + p_vaddr + j
    put(BASE + p_vaddr + j, valphins);
    // Interpretation 3: address = p_vaddr + j  (raw virtual addresses)
    put(p_vaddr + j, val);
  }
}

process.stdout.write(JSON.stringify(result) + '\n');
